/*
 * Theme hook: day is the default. Night applies when an ancestor
 * (typically <html>) carries data-theme="night". Adjust the selector
 * here if Myelin toggles themes with a different attribute or class.
 */

.empty-state {
  /* Day tokens */
  --es-surface: #f7f5f0;
  --es-border: #e2ddd2;
  --es-title: #1f2a36;
  --es-message: #5b6572;
  --es-accent: #3d6b5c;
  --es-accent-text: #ffffff;
  --es-accent-hover: #335a4d;
  --es-focus: #2b5fd9;

  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  width: 100%;
  max-width: 28rem;
  margin: 0 auto;
  padding: 2.5rem 1.5rem;
  text-align: center;
  background: var(--es-surface);
  border: 1px solid var(--es-border);
  border-radius: 14px;
  color: var(--es-title);
  font-family: inherit;
}

:root[data-theme="night"] .empty-state,
[data-theme="night"] .empty-state {
  /* Night tokens */
  --es-surface: #161b24;
  --es-border: #2a3341;
  --es-title: #e6e9ef;
  --es-message: #9aa4b2;
  --es-accent: #7fb8a4;
  --es-accent-text: #0e141c;
  --es-accent-hover: #96c9b6;
  --es-focus: #8ab4ff;
}

.empty-state__title {
  margin: 0;
  font-size: 1.25rem;
  font-weight: 600;
  line-height: 1.3;
  color: var(--es-title);
}

.empty-state__message {
  margin: 0;
  max-width: 24rem;
  font-size: 0.975rem;
  line-height: 1.55;
  color: var(--es-message);
}

.empty-state__action {
  margin-top: 0.5rem;
  min-height: 44px;
  min-width: 44px;
  padding: 0.6rem 1.25rem;
  font: inherit;
  font-weight: 600;
  line-height: 1.2;
  color: var(--es-accent-text);
  background: var(--es-accent);
  border: 1px solid transparent;
  border-radius: 999px;
  cursor: pointer;
  transition: background-color 150ms ease;
}

.empty-state__action:hover {
  background: var(--es-accent-hover);
}

.empty-state__action:active {
  transform: translateY(1px);
}

.empty-state__action:focus-visible {
  outline: 2px solid var(--es-focus);
  outline-offset: 3px;
}

@media (prefers-reduced-motion: reduce) {
  .empty-state__action {
    transition: none;
  }

  .empty-state__action:active {
    transform: none;
  }
}
